                    public Element next() {
                        File next = files.remove();
                        if (next.isDirectory()) {
                            File[] file = next.listFiles();
                            if (file != null) {
                                for (File candidate : file) {
                                    if (!candidate.equals(new File(folder, JarFile.MANIFEST_NAME))) {
                                        files.add(candidate);
                                    }
                                }
                            }
                        }
                        return new Element.ForFile(folder, next);
                    }

